import java.util.Scanner

const val M = 1000000007

fun getx(n: Long): Int {
    if (n < 30) {
        return 1 shl n.toInt()
    }
    if (n % 2 == 0L) {
        val y = getx(n shr 1)
        return (y.toLong() * y % M).toInt()
    }
    return (getx(n - 1).toLong() * 2 % M).toInt()
}

fun main() {
    val scanner = Scanner(System.`in`)
    val N = scanner.nextLong()
    val K = scanner.nextLong()

    if (N == 0L) {
        println(0)
        return
    }

    val nMod = ((N % M) * 2 - 1) % M
    val nModPositive = if (nMod < 0) nMod + M else nMod

    val z = getx(K)
    val result = (z.toLong() * nModPositive + 1) % M
    println(result)
}

